method find_closest_elements(numbers: seq<real>) returns (x: real, y: real)
  requires |numbers| >= 2
  ensures exists i, j ::
    0 <= i < |numbers| &&
    0 <= j < |numbers| &&
    i != j &&
    x == numbers[i] &&
    y == numbers[j] &&
    x <= y
{
  var bi := 0;
  var bj := 1;
  var best := if numbers[0] <= numbers[1]
              then numbers[1] - numbers[0]
              else numbers[0] - numbers[1];

  var i := 0;
  while i < |numbers|
    invariant 0 <= i <= |numbers|
    invariant 0 <= bi < |numbers|
    invariant 0 <= bj < |numbers|
    invariant bi != bj
    decreases |numbers| - i
  {
    var j := i + 1;
    while j < |numbers|
      invariant i + 1 <= j <= |numbers|
      invariant 0 <= bi < |numbers|
      invariant 0 <= bj < |numbers|
      invariant bi != bj
      decreases |numbers| - j
    {
      var diff := if numbers[i] <= numbers[j]
                  then numbers[j] - numbers[i]
                  else numbers[i] - numbers[j];

      if diff < best {
        best := diff;
        bi := i;
        bj := j;
      }
      j := j + 1;
    }
    i := i + 1;
  }

  if numbers[bi] <= numbers[bj] {
    x := numbers[bi];
    y := numbers[bj];
  } else {
    x := numbers[bj];
    y := numbers[bi];
  }
}

