lemma CardinalitySubset<T>(a: set<T>, b: set<T>)
  requires a <= b
  ensures |a| <= |b|
  decreases |b|
{
  if a != b {
    if b - a == {} {
      assert b <= a by {
        forall x | x in b
          ensures x in a
        {
          if x !in a {
            assert x in b - a;
          }
        }
      }
      assert a == b;
    }
    assert b - a != {};

    var x :| x in b - a;
    var c := b - {x};

    assert x in b;
    assert x !in a;
    assert a <= c;
    assert x !in c;
    assert b == c + {x};
    assert |b| == |c| + 1;

    CardinalitySubset(a, c);
  }
}

